import Foundation
import Testing
import ClipboardCore

@Suite struct CaptureFilterTests {
    @Test(arguments: [
        "org.nspasteboard.ConcealedType",
        "org.nspasteboard.TransientType",
        "org.nspasteboard.AutoGeneratedType",
        // Markers that predate the nspasteboard.org ones and are still
        // set by some password managers and text expanders.
        "com.agilebits.onepassword",
        "de.petermaurer.TransientPasteboardType",
        "com.typeit4me.clipping",
        "Pasteboard generator type",
    ])
    func acceptDropsConcealed(marker: String) {
        let raw = ClipContent(entries: [
            PasteboardEntry(types: [typed(TypeName.plainText, "ok")]),
            PasteboardEntry(types: [typed(TypeName.plainText, "secret"), typed(marker, "")]),
        ])
        #expect(CaptureFilter.accept(raw) == nil)
    }

    @Test func acceptDropsOversize() {
        let limit = 20 * 1024 * 1024
        #expect(CaptureFilter.maxBytes == limit)
        let exact = ClipContent(entries: [PasteboardEntry(types: [
            TypedData(type: TypeName.png, data: Data(count: limit)),
        ])])
        let over = ClipContent(entries: [PasteboardEntry(types: [
            TypedData(type: TypeName.png, data: Data(count: limit + 1)),
        ])])
        #expect(CaptureFilter.accept(exact) != nil)
        #expect(CaptureFilter.accept(over) == nil)
    }

    @Test func acceptDropsUnreadableTypes() {
        let mixed = ClipContent(entries: [
            PasteboardEntry(types: [typed(TypeName.plainText, "a"), TypedData(type: "com.example.promise", data: nil)]),
            PasteboardEntry(types: [TypedData(type: "com.example.promise", data: nil)]),
        ])
        #expect(CaptureFilter.accept(mixed) == content(typed(TypeName.plainText, "a")))

        let allUnreadable = ClipContent(entries: [
            PasteboardEntry(types: [TypedData(type: "com.example.promise", data: nil)]),
        ])
        #expect(CaptureFilter.accept(allUnreadable) == nil)
    }

    @Test func acceptDropsEmpty() {
        #expect(CaptureFilter.accept(ClipContent(entries: [])) == nil)
    }

    @Test func acceptKeepsOrdinaryContent() {
        let c = content(typed(TypeName.plainText, "hi"), typed(TypeName.rtf, "{rtf}"))
        #expect(CaptureFilter.accept(c) == c)
    }
}
